 const [now,setNow]=useState(context?.now??NOW); const [groupFilters,setGroupFilters]=useState<string[]>([]); const group=groupFilters.length===1?groupFilters[0]:'Show all'; const setGroup=(value:string)=>setGroupFilters(value==='Show all'?[]:[value]); const [statusFilters,setStatusFilters]=useState<string[]>([]); const filter=statusFilters.length===0?'All statuses':statusFilters.length===1?statusFilters[0]:'Custom'; const setFilter=(value:string)=>setStatusFilters(value==='All statuses'?[]:[value]); const [query,setQuery]=useState(''); const [selected,setSelected]=useState<number[]>([]);
 const [dialog,setDialog]=useState<{action:Action;ids:number[];scope:string}|null>(null); const [panel,setPanel]=useState(false); const [tab,setTab]=useState('Groups'); const [toast,setToast]=useState(''); const [history,setHistory]=useState<string[]>([]); const [showHistory,setShowHistory]=useState(false); const [released,setReleased]=useState(false); const [ack,setAck]=useState(false);
