 const [panelClosing,setPanelClosing]=useState(false);
 const closePanel=useCallback(()=>{if(layout==='05'&&controlConcept!=='modal')setPanelClosing(true);else setPanel(false)},[layout,controlConcept]);
 useEffect(()=>{if(!panelClosing)return;const timer=window.setTimeout(()=>{setPanel(false);setPanelClosing(false)},260);return()=>window.clearTimeout(timer)},[panelClosing]);
 const [dashboardOpen,setDashboardOpen]=useState(true); const [dashboardHidden,setDashboardHidden]=useState(false); const [groupsOpen,setGroupsOpen]=useState(false);
