 useEffect(()=>{if(!dialog&&!panel&&!help)return; const previous=document.activeElement as HTMLElement; modalRef.current?.focus({preventScroll:true});const key=(e:KeyboardEvent)=>{if(e.key==='Escape'){if(dialog)closeAction();else{closePanel();setHelp(false)}}if(e.key==='Tab'){const els=modalRef.current?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select,summary,[tabindex="0"]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===modalRef.current)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',key);return()=>{document.removeEventListener('keydown',key);previous?.focus({preventScroll:true})}},[dialog,panel,help,controlConcept,closePanel,closeAction]);
