 const open=(action:Action,ids:number[],scope:string)=>{const candidates=rows.filter(s=>ids.includes(s.id)&&eligible(s,action));const needsChoice=action==='Resume'&&(candidates.some(s=>new Date(s.due).getTime()<=now)||new Set(candidates.map(s=>s.mode==='Scheduled'&&s.previous!=='Scheduled')).size>1);setAck(false);setOpts({policy:needsChoice?'':'automatic',due:'2026-09-28T15:00',start:'2026-09-28T09:00',fresh:false,minutes:TEST_DURATION_MINUTES,group:`Group ${groups.length+1}`});setDialog({action,ids,scope})};
 const validationExample=(example:string)=>{if(!example)return;setRunning(false);setNow(NOW);setScenario('Before due date');setGroupFilters([]);setStatusFilters([]);setQuery('');setProgressFilter(null);setResultFilters([]);setReleased(example==='released');setAck(false);setPanel(false);setLayout('05');setSelected([]);const base=testDemoRows('Before due date');let action:Action='Resume';let ids:number[];if(example==='empty'){setRows(base.map(s=>({...s,status:'Completed'})));action='Pause';ids=base.map(s=>s.id)}else if(example==='dates'){setRows(base);action='Reschedule';ids=base.filter(s=>eligible(s,action)).map(s=>s.id)}else{const paused=base.map(s=>s.status==='Completed'?s:{...s,previous:s.status==='Paused'?(s.previous??'In progress'):s.status,status:'Paused' as const,pausedAt:NOW-300000});setRows(paused);ids=paused.filter(s=>s.status==='Paused').map(s=>s.id)}setOpts({policy:example==='choice'?'':'automatic',due:example==='dates'?'2026-09-28T08:00':'2026-09-28T15:00',start:'2026-09-28T09:00',fresh:false,minutes:40,group:'Group 4'});setDialog({action,ids,scope:'Everyone assigned'});};
