 const expired=affected.some(s=>new Date(s.due).getTime()<=now); const risk=released&&dialog&&['Resume','Restart','Start now'].includes(dialog.action)&&!(dialog.action==='Resume'&&opts.policy==='close');
 const datesRequired=dialog&&(['Reschedule','Reassign','Restart'].includes(dialog.action)||dialog.action==='Resume'&&opts.policy==='custom');
 const dueTime=Date.parse(opts.due),startTime=Date.parse(opts.start);
 const startRequired=!!dialog&&['Reschedule','Reassign'].includes(dialog.action);
