 const dueError=datesRequired&&(!Number.isFinite(dueTime)?'Enter a due date and time.':dueTime<=now?'Due date must be in the future.':startRequired&&Number.isFinite(startTime)&&dueTime<=startTime?'Due date must be after the start date.':dialog?.action==='Resume'&&!waitingStartNow&&waiting.some(s=>dueTime<=Date.parse(s.start))?'Due date must be after every affected student’s scheduled start.':'');
 const minutesRequired=!!dialog&&(dialog.action==='Reassign'||progressive&&dialog.action==='Restart');
 const minutesError=minutesRequired&&(!Number.isFinite(opts.minutes)||opts.minutes<1||opts.minutes>240)?'Enter a time allowance from 1 to 240 minutes.':'';
 const groupError=dialog?.action==='Reassign'&&!opts.group.trim()?'Enter a name for the new group.':'';
 const policyError=dialog?.action==='Resume'&&(!opts.policy||expired&&opts.policy==='automatic');
 const blocked=!affected.length||!!startError||!!dueError||!!minutesError||!!groupError||policyError||risk&&!ack;

 function commit(){if(!dialog||blocked)return;setRows(rs=>applyAction(rs,dialog.ids,dialog.action,opts,now));const text=`${dialog.action}: ${affected.length} student${affected.length===1?'':'s'} · ${dialog.scope}`;setToast(text);setHistory(h=>[`${new Date(now).toLocaleTimeString('en-AU')} — ${text}`,...h]);setDialog(null);setSelected([])}
 const buttons=(students:Attempt[],scope:string,compact=false)=><div className="tc-actions">{(compact?(['Pause','Resume','Start now'] as Action[]):actions).map(a=>{const count=students.filter(s=>eligible(s,a)).length;return <button key={a} disabled={!count} className={a==='Pause'?'tc-primary':''} onClick={()=>open(a,students.map(s=>s.id),scope)}><span>{symbols[a]}</span> {a}{!compact&&count>0?<small>{count}</small>:null}</button>})}</div>;

 const scoped=rows.filter(s=>!hasMultipleGroups||!groupFilters.length||groupFilters.includes(s.group));
