 useEffect(()=>{if(released||progressive)return;const end=Math.max(...rows.map(s=>Date.parse(s.expires||s.due)));const nextDay=new Date(end);nextDay.setHours(24,0,0,0);if(releasePolicy==='available'&&readyCount>0||releasePolicy==='custom'&&releaseTime&&now>=Date.parse(releaseTime)||releasePolicy==='ended'&&now>=nextDay.getTime())setReleased(true)},[now,releasePolicy,releaseTime,readyCount,released,progressive]);
